import { useState } from 'react';
import { JxTagInput, JxChip } from '@jinx-ui/react';

export interface ArticleTagPickerProps {
  value?: string[];
  defaultValue?: string[];
  onChange?: (tags: string[]) => void;
  label?: string;
  placeholder?: string;
}

export default function ArticleTagPicker({
  value,
  defaultValue = [],
  onChange,
  label = 'Теги статьи',
  placeholder = 'Введите тег и нажмите Enter',
}: ArticleTagPickerProps) {
  const [internalTags, setInternalTags] = useState<string[]>(defaultValue);
  const tags = value ?? internalTags;

  const updateTags = (next: string[]) => {
    if (value === undefined) {
      setInternalTags(next);
    }
    onChange?.(next);
  };

  const removeTag = (tag: string) => {
    updateTags(tags.filter((item) => item !== tag));
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
      <JxTagInput
        ariaLabel={label}
        placeholder={placeholder}
        value={tags}
        onValueChange={updateTags}
      />
      {tags.length > 0 && (
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
          {tags.map((tag) => (
            <JxChip key={tag} removable onRemove={() => removeTag(tag)}>
              {tag}
            </JxChip>
          ))}
        </div>
      )}
    </div>
  );
}

